  --border-strong: #3a4050;
  --text: #ecedf1;
  --text-muted: #a4a8b6;
  --text-dim: #797f90;
  --accent: #c8a15a;       /* warm brass */
  --accent-hover: #d8b06a;
  --accent-ink: #1a1408;
  --danger: #ff6b6b;
  --success: #6bd29c;
  --focus: #ffd166;
  --radius: 10px;
  --radius-lg: 16px;
  --maxw: 1200px;
  --shadow: 0 6px 24px rgba(0,0,0,0.4);
