}

* { box-sizing: border-box; }

html, body {
  margin: 0;
  padding: 0;
  background: var(--bg);
  color: var(--text);
  font-family: 'Inter', system-ui, -apple-system, Segoe UI, Roboto, Helvetica, Arial, sans-serif;
  font-size: 16px;
  line-height: 1.55;
  -webkit-font-smoothing: antialiased;
}

img { max-width: 100%; display: block; }

a { color: var(--text); text-decoration: none; }
a:hover { color: var(--accent-hover); }

/* Focus — visible against dark backgrounds */
:focus-visible {
  outline: 3px solid var(--focus);
  outline-offset: 2px;
  border-radius: 4px;
}

.visually-hidden {
  position: absolute !important;
  width: 1px; height: 1px;
  padding: 0; margin: -1px;
  overflow: hidden; clip: rect(0,0,0,0);
  white-space: nowrap; border: 0;
}

.skip-link {
  position: absolute;
  left: 0; top: 0;
  background: var(--accent);
  color: var(--accent-ink);
  padding: 10px 16px;
  font-weight: 600;
  border-radius: 0 0 8px 0;
  transform: translateY(-120%);
  transition: transform 0.15s ease;
  z-index: 100;
}
.skip-link:focus { transform: translateY(0); color: var(--accent-ink); }

.container {
  width: 100%;
  max-width: var(--maxw);
  margin: 0 auto;
  padding: 0 24px;
}

/* ==== Header ==== */
.site-header {
  position: sticky;
  top: 0;
  z-index: 50;
  background: rgba(11, 12, 16, 0.85);
  backdrop-filter: blur(10px);
  border-bottom: 1px solid var(--border);
}

.announcement {
  background: var(--bg-elev-2);
  color: var(--text-muted);
  text-align: center;
  font-size: 0.825rem;
  padding: 8px 16px;
  border-bottom: 1px solid var(--border);
}
.announcement strong { color: var(--accent); }

.header-inner {
  display: flex;
  align-items: center;
  gap: 24px;
  padding: 16px 0;
}

.brand {
  font-family: 'Cormorant Garamond', 'Georgia', serif;
  font-size: 1.6rem;
  font-weight: 600;
  letter-spacing: 0.08em;
  color: var(--text);
  flex-shrink: 0;
}
.brand .dot { color: var(--accent); }

.primary-nav {
  flex: 1;
}
.primary-nav ul {
  list-style: none;
  display: flex;
  gap: 24px;
  margin: 0; padding: 0;
}
.primary-nav a {
  display: inline-block;
  padding: 8px 4px;
  font-size: 0.92rem;
  color: var(--text-muted);
  font-weight: 500;
  border-bottom: 2px solid transparent;
  transition: color 0.15s, border-color 0.15s;
}
.primary-nav a:hover,
.primary-nav a[aria-current="page"] {
  color: var(--text);
  border-bottom-color: var(--accent);
}

.header-actions {
  display: flex;
  align-items: center;
  gap: 4px;
}

.icon-btn {
  background: transparent;
  border: 1px solid transparent;
  color: var(--text);
  width: 40px; height: 40px;
  display: inline-flex;
  align-items: center; justify-content: center;
  border-radius: 8px;
  cursor: pointer;
  position: relative;
}
.icon-btn:hover { background: var(--bg-elev); }
.icon-btn svg { width: 20px; height: 20px; }

.cart-count {
  position: absolute;
  top: 4px; right: 4px;
  min-width: 18px; height: 18px;
  padding: 0 5px;
  border-radius: 9px;
  background: var(--accent);
  color: var(--accent-ink);
  font-size: 0.7rem;
  font-weight: 700;
  display: inline-flex;
  align-items: center; justify-content: center;
}

.menu-toggle { display: none; }

/* ==== Buttons ==== */
.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  padding: 12px 22px;
  font-size: 0.95rem;
  font-weight: 600;
  border-radius: 8px;
  border: 1px solid transparent;
  cursor: pointer;
  font-family: inherit;
  text-decoration: none;
  transition: background 0.15s, color 0.15s, border-color 0.15s;
  min-height: 44px;
}
.btn-primary {
  background: var(--accent);
  color: var(--accent-ink);
}
.btn-primary:hover { background: var(--accent-hover); color: var(--accent-ink); }

.btn-ghost {
  background: transparent;
  color: var(--text);
  border-color: var(--border-strong);
}
.btn-ghost:hover { background: var(--bg-elev); border-color: var(--text-muted); }

.btn-link {
  background: transparent;
  border: none;
  color: var(--accent);
  padding: 4px 0;
  font-weight: 600;
  cursor: pointer;
  font-family: inherit;
  font-size: 0.95rem;
}
.btn-link:hover { color: var(--accent-hover); }

/* ==== Hero ==== */
.hero {
  position: relative;
  overflow: hidden;
  background:
    radial-gradient(1100px 500px at 80% -10%, rgba(200,161,90,0.18), transparent 60%),
    radial-gradient(800px 400px at 0% 100%, rgba(120,80,200,0.10), transparent 60%),
    var(--bg);
  border-bottom: 1px solid var(--border);
}
.hero-inner {
  display: grid;
  grid-template-columns: 1.1fr 1fr;
  gap: 48px;
  align-items: center;
  padding: 80px 0 96px;
}
.hero-eyebrow {
  display: inline-block;
  font-size: 0.78rem;
  letter-spacing: 0.18em;
  text-transform: uppercase;
  color: var(--accent);
  margin-bottom: 16px;
  font-weight: 600;
}
.hero h1 {
  font-family: 'Cormorant Garamond', Georgia, serif;
  font-size: clamp(2.4rem, 5.5vw, 4.2rem);
  line-height: 1.05;
  margin: 0 0 20px;
  font-weight: 500;
  letter-spacing: -0.01em;
}
.hero h1 em {
  font-style: italic;
  color: var(--accent);
}
.hero p.lede {
  font-size: 1.1rem;
  color: var(--text-muted);
  max-width: 52ch;
  margin: 0 0 32px;
}
.hero-cta {
  display: flex;
  flex-wrap: wrap;
  gap: 12px;
}
.hero-art {
  position: relative;
  aspect-ratio: 4/5;
  border-radius: var(--radius-lg);
  overflow: hidden;
  background: linear-gradient(135deg, #2a2230 0%, #14161d 100%);
  border: 1px solid var(--border);
  box-shadow: var(--shadow);
}
.hero-art svg { width: 100%; height: 100%; display: block; }
.hero-badge {
  position: absolute;
  bottom: 20px; left: 20px;
  background: rgba(11,12,16,0.85);
  backdrop-filter: blur(8px);
  border: 1px solid var(--border-strong);
  padding: 12px 16px;
  border-radius: 10px;
  font-size: 0.85rem;
  color: var(--text);
}
.hero-badge strong { color: var(--accent); display: block; font-size: 1.05rem; }

/* ==== Sections ==== */
section { padding: 72px 0; }
section + section { padding-top: 0; }

.section-head {
  display: flex;
  align-items: end;
  justify-content: space-between;
  gap: 24px;
  margin-bottom: 32px;
  flex-wrap: wrap;
}
.section-head h2 {
  font-family: 'Cormorant Garamond', Georgia, serif;
  font-size: clamp(1.8rem, 3.5vw, 2.4rem);
  margin: 0 0 4px;
  font-weight: 500;
  letter-spacing: -0.01em;
}
.section-head p.kicker {
  font-size: 0.78rem;
  letter-spacing: 0.18em;
  text-transform: uppercase;
  color: var(--accent);
  margin: 0 0 8px;
  font-weight: 600;
}
.section-head .sub {
  color: var(--text-muted);
  margin: 0;
  max-width: 50ch;
}

/* Category filters (toggle group, semantic tablist not warranted — use buttons) */
.filter-bar {
  display: flex;
  gap: 8px;
  flex-wrap: wrap;
  margin-bottom: 28px;
}
.filter-bar button {
  background: var(--bg-elev);
  color: var(--text-muted);
  border: 1px solid var(--border);
  padding: 8px 16px;
  border-radius: 999px;
  font-size: 0.85rem;
  font-weight: 500;
  cursor: pointer;
  font-family: inherit;
  min-height: 36px;
}
.filter-bar button:hover { color: var(--text); border-color: var(--border-strong); }
.filter-bar button[aria-pressed="true"] {
  background: var(--accent);
  color: var(--accent-ink);
  border-color: var(--accent);
}

/* ==== Product grid ==== */
.product-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(240px, 1fr));
  gap: 24px;
}

.product-card {
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: var(--radius-lg);
  overflow: hidden;
  display: flex;
  flex-direction: column;
  transition: transform 0.2s, border-color 0.2s;
  position: relative;
}
.product-card:hover {
  transform: translateY(-3px);
  border-color: var(--border-strong);
}
.product-media {
  position: relative;
  aspect-ratio: 1;
  background: var(--bg-elev);
  overflow: hidden;
}
.product-media svg { width: 100%; height: 100%; }

.product-badge {
  position: absolute;
  top: 12px; left: 12px;
  background: var(--bg);
  color: var(--accent);
  font-size: 0.7rem;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  padding: 4px 10px;
  border-radius: 999px;
  font-weight: 700;
  border: 1px solid var(--border-strong);
}
.product-badge.sale { background: var(--danger); color: #2a0808; border-color: transparent; }
.product-badge.new { background: var(--accent); color: var(--accent-ink); border-color: transparent; }

.wishlist-btn {
  position: absolute;
  top: 10px; right: 10px;
  background: rgba(11,12,16,0.7);
  border: 1px solid var(--border-strong);
  color: var(--text);
  width: 36px; height: 36px;
  border-radius: 50%;
  display: inline-flex;
  align-items: center; justify-content: center;
  cursor: pointer;
}
.wishlist-btn:hover { background: var(--bg); }
.wishlist-btn svg { width: 18px; height: 18px; }
.wishlist-btn[aria-pressed="true"] { color: var(--danger); border-color: var(--danger); }

.product-body {
  padding: 16px 18px 20px;
  display: flex;
  flex-direction: column;
  gap: 8px;
  flex: 1;
}
.product-cat {
  font-size: 0.72rem;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  color: var(--text-dim);
  font-weight: 600;
}
.product-name {
  font-size: 1rem;
  font-weight: 600;
  margin: 0;
  color: var(--text);
}
.product-name a {
  color: inherit;
