+/* ==== Noctis — dark ecommerce home ==== */
+:root {
+  --bg: #0b0c10;
+  --bg-elev: #14161d;
+  --bg-elev-2: #1c1f29;
+  --surface: #11131a;
+  --border: #2a2e3a;
+  --border-strong: #3a4050;
+  --text: #ecedf1;
+  --text-muted: #a4a8b6;
+  --text-dim: #797f90;
+  --accent: #c8a15a;       /* warm brass */
+  --accent-hover: #d8b06a;
+  --accent-ink: #1a1408;
+  --danger: #ff6b6b;
+  --success: #6bd29c;
+  --focus: #ffd166;
+  --radius: 10px;
+  --radius-lg: 16px;
+  --maxw: 1200px;
+  --shadow: 0 6px 24px rgba(0,0,0,0.4);
+  font-synthesis: none;
+}
+
+* { box-sizing: border-box; }
+
+html, body {
+  margin: 0;
+  padding: 0;
+  background: var(--bg);
+  color: var(--text);
+  font-family: 'Inter', system-ui, -apple-system, Segoe UI, Roboto, Helvetica, Arial, sans-serif;
+  font-size: 16px;
+  line-height: 1.55;
+  -webkit-font-smoothing: antialiased;
+}
+
+img { max-width: 100%; display: block; }
+
+a { color: var(--text); text-decoration: none; }
+a:hover { color: var(--accent-hover); }
+
+/* Focus — visible against dark backgrounds */
+:focus-visible {
+  outline: 3px solid var(--focus);
+  outline-offset: 2px;
+  border-radius: 4px;
+}
+
+.visually-hidden {
+  position: absolute !important;
+  width: 1px; height: 1px;
+  padding: 0; margin: -1px;
+  overflow: hidden; clip: rect(0,0,0,0);
+  white-space: nowrap; border: 0;
+}
+
+.skip-link {
+  position: absolute;
+  left: 0; top: 0;
+  background: var(--accent);
+  color: var(--accent-ink);
+  padding: 10px 16px;
+  font-weight: 600;
+  border-radius: 0 0 8px 0;
+  transform: translateY(-120%);
+  transition: transform 0.15s ease;
+  z-index: 100;
+}
+.skip-link:focus { transform: translateY(0); color: var(--accent-ink); }
+
+.container {
+  width: 100%;
+  max-width: var(--maxw);
+  margin: 0 auto;
+  padding: 0 24px;
+}
+
+/* ==== Header ==== */
+.site-header {
+  position: sticky;
+  top: 0;
+  z-index: 50;
+  background: rgba(11, 12, 16, 0.85);
+  backdrop-filter: blur(10px);
+  border-bottom: 1px solid var(--border);
+}
+
+.announcement {
+  background: var(--bg-elev-2);
+  color: var(--text-muted);
+  text-align: center;
+  font-size: 0.825rem;
+  padding: 8px 16px;
+  border-bottom: 1px solid var(--border);
+}
+.announcement strong { color: var(--accent); }
+
+.header-inner {
+  display: flex;
+  align-items: center;
+  gap: 24px;
+  padding: 16px 0;
+}
+
+.brand {
+  font-family: 'Cormorant Garamond', 'Georgia', serif;
+  font-size: 1.6rem;
+  font-weight: 600;
+  letter-spacing: 0.08em;
+  color: var(--text);
+  flex-shrink: 0;
+}
+.brand .dot { color: var(--accent); }
+
+.primary-nav {
+  flex: 1;
+}
+.primary-nav ul {
+  list-style: none;
+  display: flex;
+  gap: 24px;
+  margin: 0; padding: 0;
+}
+.primary-nav a {
+  display: inline-block;
+  padding: 8px 4px;
+  font-size: 0.92rem;
+  color: var(--text-muted);
+  font-weight: 500;
+  border-bottom: 2px solid transparent;
+  transition: color 0.15s, border-color 0.15s;
+}
+.primary-nav a:hover,
+.primary-nav a[aria-current="page"] {
+  color: var(--text);
+  border-bottom-color: var(--accent);
+}
+
+.header-actions {
+  display: flex;
+  align-items: center;
+  gap: 4px;
+}
+
+.icon-btn {
+  background: transparent;
+  border: 1px solid transparent;
+  color: var(--text);
+  width: 40px; height: 40px;
+  display: inline-flex;
+  align-items: center; justify-content: center;
+  border-radius: 8px;
+  cursor: pointer;
+  position: relative;
+}
+.icon-btn:hover { background: var(--bg-elev); }
+.icon-btn svg { width: 20px; height: 20px; }
+
+.cart-count {
+  position: absolute;
+  top: 4px; right: 4px;
+  min-width: 18px; height: 18px;
+  padding: 0 5px;
+  border-radius: 9px;
+  background: var(--accent);
+  color: var(--accent-ink);
+  font-size: 0.7rem;
+  font-weight: 700;
+  display: inline-flex;
+  align-items: center; justify-content: center;
+}
+
+.menu-toggle { display: none; }
+
+/* ==== Buttons ==== */
+.btn {
+  display: inline-flex;
+  align-items: center;
+  justify-content: center;
+  gap: 8px;
+  padding: 12px 22px;
+  font-size: 0.95rem;
+  font-weight: 600;
+  border-radius: 8px;
+  border: 1px solid transparent;
+  cursor: pointer;
+  font-family: inherit;
+  text-decoration: none;
+  transition: background 0.15s, color 0.15s, border-color 0.15s;
+  min-height: 44px;
+}
+.btn-primary {
+  background: var(--accent);
+  color: var(--accent-ink);
+}
+.btn-primary:hover { background: var(--accent-hover); color: var(--accent-ink); }
+
+.btn-ghost {
+  background: transparent;
+  color: var(--text);
+  border-color: var(--border-strong);
+}
+.btn-ghost:hover { background: var(--bg-elev); border-color: var(--text-muted); }
+
+.btn-link {
+  background: transparent;
+  border: none;
+  color: var(--accent);
+  padding: 4px 0;
+  font-weight: 600;
+  cursor: pointer;
+  font-family: inherit;
+  font-size: 0.95rem;
+}
+.btn-link:hover { color: var(--accent-hover); }
+
+/* ==== Hero ==== */
+.hero {
+  position: relative;
+  overflow: hidden;
+  background:
+    radial-gradient(1100px 500px at 80% -10%, rgba(200,161,90,0.18), transparent 60%),
+    radial-gradient(800px 400px at 0% 100%, rgba(120,80,200,0.10), transparent 60%),
+    var(--bg);
+  border-bottom: 1px solid var(--border);
+}
+.hero-inner {
+  display: grid;
+  grid-template-columns: 1.1fr 1fr;
+  gap: 48px;
+  align-items: center;
+  padding: 80px 0 96px;
+}
+.hero-eyebrow {
+  display: inline-block;
+  font-size: 0.78rem;
+  letter-spacing: 0.18em;
+  text-transform: uppercase;
+  color: var(--accent);
+  margin-bottom: 16px;
+  font-weight: 600;
+}
+.hero h1 {
+  font-family: 'Cormorant Garamond', Georgia, serif;
+  font-size: clamp(2.4rem, 5.5vw, 4.2rem);
+  line-height: 1.05;
+  margin: 0 0 20px;
+  font-weight: 500;
+  letter-spacing: -0.01em;
+}
+.hero h1 em {
+  font-style: italic;
+  color: var(--accent);
+}
+.hero p.lede {
+  font-size: 1.1rem;
+  color: var(--text-muted);
+  max-width: 52ch;
+  margin: 0 0 32px;
+}
+.hero-cta {
+  display: flex;
+  flex-wrap: wrap;
+  gap: 12px;
+}
+.hero-art {
+  position: relative;
+  aspect-ratio: 4/5;
+  border-radius: var(--radius-lg);
+  overflow: hidden;
+  background: linear-gradient(135deg, #2a2230 0%, #14161d 100%);
+  border: 1px solid var(--border);
+  box-shadow: var(--shadow);
+}
+.hero-art svg { width: 100%; height: 100%; display: block; }
+.hero-badge {
+  position: absolute;
+  bottom: 20px; left: 20px;
+  background: rgba(11,12,16,0.85);
+  backdrop-filter: blur(8px);
+  border: 1px solid var(--border-strong);
+  padding: 12px 16px;
+  border-radius: 10px;
+  font-size: 0.85rem;
+  color: var(--text);
+}
+.hero-badge strong { color: var(--accent); display: block; font-size: 1.05rem; }
+
+/* ==== Sections ==== */
+section { padding: 72px 0; }
+section + section { padding-top: 0; }
+
+.section-head {
+  display: flex;
+  align-items: end;
+  justify-content: space-between;
+  gap: 24px;
+  margin-bottom: 32px;
+  flex-wrap: wrap;
+}
+.section-head h2 {
+  font-family: 'Cormorant Garamond', Georgia, serif;
+  font-size: clamp(1.8rem, 3.5vw, 2.4rem);
+  margin: 0 0 4px;
+  font-weight: 500;
+  letter-spacing: -0.01em;
+}
+.section-head p.kicker {
+  font-size: 0.78rem;
+  letter-spacing: 0.18em;
+  text-transform: uppercase;
+  color: var(--accent);
+  margin: 0 0 8px;
+  font-weight: 600;
+}
+.section-head .sub {
+  color: var(--text-muted);
+  margin: 0;
+  max-width: 50ch;
+}
+
+/* Category filters (toggle group, semantic tablist not warranted — use buttons) */
+.filter-bar {
+  display: flex;
+  gap: 8px;
+  flex-wrap: wrap;
+  margin-bottom: 28px;
+}
+.filter-bar button {
+  background: var(--bg-elev);
+  color: var(--text-muted);
+  border: 1px solid var(--border);
+  padding: 8px 16px;
+  border-radius: 999px;
+  font-size: 0.85rem;
+  font-weight: 500;
+  cursor: pointer;
+  font-family: inherit;
+  min-height: 36px;
+}
+.filter-bar button:hover { color: var(--text); border-color: var(--border-strong); }
+.filter-bar button[aria-pressed="true"] {
+  background: var(--accent);
+  color: var(--accent-ink);
+  border-color: var(--accent);
+}
+
+/* ==== Product grid ==== */
+.product-grid {
+  display: grid;
+  grid-template-columns: repeat(auto-fill, minmax(240px, 1fr));
+  gap: 24px;
+}
+
+.product-card {
+  background: var(--surface);
+  border: 1px solid var(--border);
+  border-radius: var(--radius-lg);
+  overflow: hidden;
+  display: flex;
+  flex-direction: column;
+  transition: transform 0.2s, border-color 0.2s;
+  position: relative;
+}
+.product-card:hover {
+  transform: translateY(-3px);
+  border-color: var(--border-strong);
+}
+.product-media {
+  position: relative;
+  aspect-ratio: 1;
+  background: var(--bg-elev);
+  overflow: hidden;
+}
+.product-media svg { width: 100%; height: 100%; }
+
+.product-badge {
+  position: absolute;
+  top: 12px; left: 12px;
+  background: var(--bg);
+  color: var(--accent);
+  font-size: 0.7rem;
+  letter-spacing: 0.12em;
+  text-transform: uppercase;
+  padding: 4px 10px;
+  border-radius: 999px;
+  font-weight: 700;
+  border: 1px solid var(--border-strong);
+}
+.product-badge.sale { background: var(--danger); color: #2a0808; border-color: transparent; }
+.product-badge.new { background: var(--accent); color: var(--accent-ink); border-color: transparent; }
+
+.wishlist-btn {
+  position: absolute;
+  top: 10px; right: 10px;
+  background: rgba(11,12,16,0.7);
+  border: 1px solid var(--border-strong);
+  color: var(--text);
+  width: 36px; height: 36px;
+  border-radius: 50%;
+  display: inline-flex;
+  align-items: center; justify-content: center;
+  cursor: pointer;
+}
+.wishlist-btn:hover { background: var(--bg); }
+.wishlist-btn svg { width: 18px; height: 18px; }
+.wishlist-btn[aria-pressed="true"] { color: var(--danger); border-color: var(--danger); }
+
+.product-body {
+  padding: 16px 18px 20px;
+  display: flex;
+  flex-direction: column;
+  gap: 8px;
+  flex: 1;
+}
+.product-cat {
+  font-size: 0.72rem;
+  letter-spacing: 0.14em;
+  text-transform: uppercase;
+  color: var(--text-dim);
+  font-weight: 600;
+}
+.product-name {
+  font-size: 1rem;
+  font-weight: 600;
+  margin: 0;
+  color: var(--text);
+}
+.product-name a {
+  color: inherit;
+  /* Make whole card clickable but keep card decorative */
+}
+.product-name a::after {
+  content: "";
+  position: absolute;
+  inset: 0;
+}
+.product-rating {
+  display: inline-flex;
+  align-items: center;
+  gap: 6px;
+  font-size: 0.82rem;
+  color: var(--text-muted);
+}
+.stars {
+  display: inline-flex;
+  color: var(--accent);
+  letter-spacing: 1px;
+}
+.product-price-row {
+  display: flex;
+  align-items: baseline;
+  gap: 10px;
+  margin-top: auto;
+}
+.price-now {
+  font-size: 1.05rem;
+  font-weight: 700;
+  color: var(--text);
+}
+.price-was {
+  font-size: 0.9rem;
+  color: var(--text-dim);
+  text-decoration: line-through;
+}
+.price-save {
+  font-size: 0.78rem;
+  color: var(--success);
+  font-weight: 600;
+}
+
+/* ==== Deals: Countdown banner + grid ==== */
+.deals {
+  background: linear-gradient(180deg, transparent, rgba(200,161,90,0.04));
+}
+.deal-banner {
+  display: grid;
+  grid-template-columns: 1fr auto;
+  gap: 24px;
+  align-items: center;
+  background: linear-gradient(135deg, #1c1410 0%, #14161d 60%);
+  border: 1px solid var(--border-strong);
+  border-radius: var(--radius-lg);
+  padding: 28px 32px;
+  margin-bottom: 32px;
+}
+.deal-banner h3 {
+  font-family: 'Cormorant Garamond', Georgia, serif;
+  font-size: 1.6rem;
+  margin: 0 0 6px;
+  font-weight: 500;
+}
+.deal-banner p { margin: 0; color: var(--text-muted); }
+.countdown {
+  display: flex;
+  gap: 10px;
+}
+.countdown div {
+  background: var(--bg);
+  border: 1px solid var(--border);
+  border-radius: 8px;
+  padding: 10px 14px;
+  min-width: 64px;
+  text-align: center;
+}
+.countdown .num {
+  font-size: 1.4rem;
+  font-weight: 700;
+  font-variant-numeric: tabular-nums;
+  color: var(--accent);
+  display: block;
+  line-height: 1;
+}
+.countdown .lbl {
+  font-size: 0.65rem;
+  letter-spacing: 0.14em;
+  text-transform: uppercase;
+  color: var(--text-dim);
+  margin-top: 4px;
+  display: block;
+}
+
+/* ==== Editorial ==== */
+.editorial-grid {
+  display: grid;
+  grid-template-columns: 2fr 1fr 1fr;
+  grid-template-rows: 1fr 1fr;
+  gap: 20px;
+  min-height: 560px;
+}
+.editorial-card {
+  position: relative;
+  border-radius: var(--radius-lg);
+  overflow: hidden;
+  background: var(--bg-elev);
+  border: 1px solid var(--border);
+  display: flex;
+  flex-direction: column;
+  justify-content: flex-end;
+  min-height: 220px;
+  isolation: isolate;
+}
+.editorial-card:nth-child(1) { grid-row: 1 / span 2; }
+.editorial-bg {
+  position: absolute;
+  inset: 0;
+  z-index: -1;
+}
+.editorial-bg svg { width: 100%; height: 100%; }
+.editorial-card::after {
+  content: "";
+  position: absolute; inset: 0;
+  background: linear-gradient(180deg, rgba(11,12,16,0) 30%, rgba(11,12,16,0.92) 100%);
+  z-index: -1;
+}
+.editorial-body {
+  padding: 24px;
+  position: relative;
+}
+.editorial-tag {
+  font-size: 0.7rem;
+  letter-spacing: 0.16em;
+  text-transform: uppercase;
+  color: var(--accent);
+  font-weight: 700;
+  margin-bottom: 8px;
+  display: block;
+}
+.editorial-card h3 {
+  font-family: 'Cormorant Garamond', Georgia, serif;
+  font-size: 1.4rem;
+  margin: 0 0 6px;
+  font-weight: 500;
+  line-height: 1.2;
+}
+.editorial-card:nth-child(1) h3 { font-size: 2rem; }
+.editorial-card p {
+  margin: 0 0 12px;
+  color: var(--text-muted);
+  font-size: 0.9rem;
+}
+.editorial-card a {
+  color: var(--text);
+  font-weight: 600;
+  font-size: 0.9rem;
+}
+.editorial-card a::after {
+  content: "";
+  position: absolute; inset: 0;
+}
+.editorial-card a:hover { color: var(--accent); }
+
+/* ==== Newsletter ==== */
+.newsletter {
+  background: var(--bg-elev);
+  border-top: 1px solid var(--border);
+  border-bottom: 1px solid var(--border);
+}
+.newsletter-inner {
+  display: grid;
+  grid-template-columns: 1fr 1fr;
+  gap: 40px;
+  align-items: center;
+}
+.newsletter h2 {
+  font-family: 'Cormorant Garamond', Georgia, serif;
+  font-size: 2rem;
+  margin: 0 0 8px;
+  font-weight: 500;
+}
+.newsletter p { color: var(--text-muted); margin: 0; }
+
+.newsletter-form {
+  display: flex;
+  gap: 8px;
+  flex-wrap: wrap;
+}
+.newsletter-form .field {
+  flex: 1 1 240px;
+  display: flex;
+  flex-direction: column;
+  gap: 4px;
+}
+.newsletter-form label { font-size: 0.85rem; color: var(--text-muted); }
+.newsletter-form input {
+  background: var(--bg);
+  color: var(--text);
+  border: 1px solid var(--border-strong);
+  border-radius: 8px;
+  padding: 12px 14px;
+  font-size: 1rem;
+  font-family: inherit;
+  min-height: 44px;
+}
+.newsletter-form input:focus-visible {
+  outline: 3px solid var(--focus);
+  outline-offset: 2px;
+  border-color: var(--accent);
+}
+.newsletter-form input[aria-invalid="true"] {
+  border-color: var(--danger);
+}
+.field-error {
+  color: var(--danger);
+  font-size: 0.82rem;
+  margin: 0;
+}
+.field-success {
+  color: var(--success);
+  font-size: 0.92rem;
+  margin: 8px 0 0;
+}
+.newsletter-form button { align-self: end; }
+
+/* ==== Footer ==== */
+.site-footer {
+  background: var(--bg);
+  padding: 60px 0 24px;
+  color: var(--text-muted);
+  font-size: 0.9rem;
+}
+.footer-grid {
+  display: grid;
+  grid-template-columns: 2fr repeat(3, 1fr);
+  gap: 40px;
+  margin-bottom: 40px;
+}
+.footer-grid h3 {
+  color: var(--text);
+  font-size: 0.85rem;
+  letter-spacing: 0.14em;
+  text-transform: uppercase;
+  margin: 0 0 16px;
+  font-weight: 600;
+}
+.footer-grid ul { list-style: none; padding: 0; margin: 0; display: flex; flex-direction: column; gap: 10px; }
+.footer-grid a { color: var(--text-muted); }
+.footer-grid a:hover { color: var(--text); }
+.footer-brand p { max-width: 36ch; margin: 12px 0 0; }
+.footer-bottom {
+  border-top: 1px solid var(--border);
+  padding-top: 20px;
+  display: flex;
+  justify-content: space-between;
+  flex-wrap: wrap;
+  gap: 12px;
+  font-size: 0.82rem;
+  color: var(--text-dim);
+}
+.socials { display: flex; gap: 8px; }
+.socials a {
+  width: 36px; height: 36px;
+  display: inline-flex; align-items: center; justify-content: center;
+  border: 1px solid var(--border);
+  border-radius: 8px;
+}
+.socials a:hover { border-color: var(--accent); color: var(--accent); }
+.socials svg { width: 16px; height: 16px; }
+
+/* ==== Loading skeleton (status example) ==== */
+.skeleton {
+  background: linear-gradient(90deg, var(--bg-elev) 0%, var(--bg-elev-2) 50%, var(--bg-elev) 100%);
+  background-size: 200% 100%;
+  animation: shimmer 1.4s infinite;
+  border-radius: 8px;
+}
+@keyframes shimmer { from { background-position: 200% 0; } to { background-position: -200% 0; } }
+
+/* ==== Responsive ==== */
+@media (max-width: 960px) {
+  .hero-inner { grid-template-columns: 1fr; padding: 56px 0 64px; }
+  .hero-art { max-width: 480px; }
+  .editorial-grid {
+    grid-template-columns: 1fr 1fr;
+    grid-template-rows: auto;
+    min-height: auto;
+  }
+  .editorial-card:nth-child(1) { grid-row: auto; grid-column: 1 / -1; min-height: 320px; }
+  .footer-grid { grid-template-columns: 1fr 1fr; }
+  .newsletter-inner { grid-template-columns: 1fr; }
+  .deal-banner { grid-template-columns: 1fr; }
+}
+
+@media (max-width: 720px) {
+  .menu-toggle {
+    display: inline-flex;
+    margin-left: auto;
+    order: 3;
+  }
+  .header-actions { order: 2; margin-left: auto; }
+  .primary-nav {
+    order: 4;
+    flex-basis: 100%;
+    display: none;
+    border-top: 1px solid var(--border);
+    padding-top: 12px;
+  }
+  .primary-nav[data-open="true"] { display: block; }
+  .primary-nav ul {
+    flex-direction: column;
+    gap: 4px;
+  }
+  .primary-nav a { display: block; padding: 10px 0; }
+  .header-inner { flex-wrap: wrap; gap: 12px; }
+  section { padding: 56px 0; }
+  .product-grid { grid-template-columns: repeat(auto-fill, minmax(160px, 1fr)); gap: 16px; }
+  .editorial-grid { grid-template-columns: 1fr; }
+  .editorial-card:nth-child(1) { min-height: 280px; }
+  .footer-grid { grid-template-columns: 1fr; gap: 28px; }
+  .deal-banner { padding: 22px; }
+}
+
+/* ==== Reduced motion ==== */
+@media (prefers-reduced-motion: reduce) {
+  *, *::before, *::after {
+    animation-duration: 0.001ms !important;
+    transition-duration: 0.001ms !important;
+  }
+  .product-card:hover { transform: none; }
+}
+
+/* ==== Forced colors ==== */
+@media (forced-colors: active) {
+  .btn, .icon-btn, .filter-bar button, .product-card, .editorial-card,
+  .newsletter-form input, .countdown div, .hero-art, .deal-banner {
+    border: 1px solid CanvasText;
+  }
+  .btn-primary, .filter-bar button[aria-pressed="true"] {
+    background: Highlight;
