.btn-link:hover { color: var(--accent-hover); }

/* ==== Hero ==== */
.hero {
  position: relative;
  overflow: hidden;
  background:
    radial-gradient(1100px 500px at 80% -10%, rgba(200,161,90,0.18), transparent 60%),
    radial-gradient(800px 400px at 0% 100%, rgba(120,80,200,0.10), transparent 60%),
    var(--bg);
  border-bottom: 1px solid var(--border);
}
.hero-inner {
  display: grid;
  grid-template-columns: 1.1fr 1fr;
  gap: 48px;
  align-items: center;
  padding: 80px 0 96px;
}
.hero-eyebrow {
  display: inline-block;
  font-size: 0.78rem;
  letter-spacing: 0.18em;
  text-transform: uppercase;
  color: var(--accent);
  margin-bottom: 16px;
  font-weight: 600;
}
.hero h1 {
  font-family: 'Cormorant Garamond', Georgia, serif;
  font-size: clamp(2.4rem, 5.5vw, 4.2rem);
  line-height: 1.05;
  margin: 0 0 20px;
  font-weight: 500;
  letter-spacing: -0.01em;
}
.hero h1 em {
  font-style: italic;
  color: var(--accent);
}
.hero p.lede {
  font-size: 1.1rem;
  color: var(--text-muted);
  max-width: 52ch;
  margin: 0 0 32px;
}
.hero-cta {
  display: flex;
  flex-wrap: wrap;
  gap: 12px;
}
.hero-art {
  position: relative;
  aspect-ratio: 4/5;
  border-radius: var(--radius-lg);
  overflow: hidden;
  background: linear-gradient(135deg, #2a2230 0%, #14161d 100%);
  border: 1px solid var(--border);
  box-shadow: var(--shadow);
}
.hero-art svg { width: 100%; height: 100%; display: block; }
.hero-badge {
  position: absolute;
