  border: 1px solid var(--border-strong);
  padding: 12px 16px;
  border-radius: 10px;
  font-size: 0.85rem;
  color: var(--text);
}
.hero-badge strong { color: var(--accent); display: block; font-size: 1.05rem; }

/* ==== Sections ==== */
section { padding: 72px 0; }
section + section { padding-top: 0; }

.section-head {
  display: flex;
  align-items: end;
  justify-content: space-between;
  gap: 24px;
  margin-bottom: 32px;
  flex-wrap: wrap;
}
.section-head h2 {
  font-family: 'Cormorant Garamond', Georgia, serif;
  font-size: clamp(1.8rem, 3.5vw, 2.4rem);
  margin: 0 0 4px;
  font-weight: 500;
  letter-spacing: -0.01em;
}
.section-head p.kicker {
  font-size: 0.78rem;
  letter-spacing: 0.18em;
  text-transform: uppercase;
  color: var(--accent);
  margin: 0 0 8px;
  font-weight: 600;
}
.section-head .sub {
  color: var(--text-muted);
  margin: 0;
  max-width: 50ch;
}

/* Category filters (toggle group, semantic tablist not warranted — use buttons) */
.filter-bar {
  display: flex;
  gap: 8px;
  flex-wrap: wrap;
  margin-bottom: 28px;
}
.filter-bar button {
  background: var(--bg-elev);
