}
.filter-bar button:hover { color: var(--text); border-color: var(--border-strong); }
.filter-bar button[aria-pressed="true"] {
  background: var(--accent);
  color: var(--accent-ink);
  border-color: var(--accent);
}

/* ==== Product grid ==== */
.product-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(240px, 1fr));
  gap: 24px;
}

.product-card {
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: var(--radius-lg);
  overflow: hidden;
  display: flex;
  flex-direction: column;
  transition: transform 0.2s, border-color 0.2s;
  position: relative;
}
.product-card:hover {
  transform: translateY(-3px);
  border-color: var(--border-strong);
}
.product-media {
  position: relative;
  aspect-ratio: 1;
  background: var(--bg-elev);
  overflow: hidden;
}
.product-media svg { width: 100%; height: 100%; }

.product-badge {
  position: absolute;
  top: 12px; left: 12px;
  background: var(--bg);
  color: var(--accent);
  font-size: 0.7rem;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  padding: 4px 10px;
  border-radius: 999px;
  font-weight: 700;
  border: 1px solid var(--border-strong);
}
.product-badge.sale { background: var(--danger); color: #2a0808; border-color: transparent; }
.product-badge.new { background: var(--accent); color: var(--accent-ink); border-color: transparent; }

.wishlist-btn {
  position: absolute;
  top: 10px; right: 10px;
  background: rgba(11,12,16,0.7);
  border: 1px solid var(--border-strong);
  color: var(--text);
  width: 36px; height: 36px;
  border-radius: 50%;
  display: inline-flex;
  align-items: center; justify-content: center;
  cursor: pointer;
}
.wishlist-btn:hover { background: var(--bg); }
.wishlist-btn svg { width: 18px; height: 18px; }
.wishlist-btn[aria-pressed="true"] { color: var(--danger); border-color: var(--danger); }

.product-body {
  padding: 16px 18px 20px;
  display: flex;
  flex-direction: column;
  gap: 8px;
  flex: 1;
}
.product-cat {
  font-size: 0.72rem;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  color: var(--text-dim);
  font-weight: 600;
}
.product-name {
  font-size: 1rem;
  font-weight: 600;
  margin: 0;
  color: var(--text);
}
.product-name a {
  color: inherit;
