}
.product-name a::after {
  content: "";
  position: absolute;
  inset: 0;
}
.product-rating {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  font-size: 0.82rem;
  color: var(--text-muted);
}
.stars {
  display: inline-flex;
  color: var(--accent);
  letter-spacing: 1px;
}
.product-price-row {
  display: flex;
  align-items: baseline;
  gap: 10px;
  margin-top: auto;
}
.price-now {
  font-size: 1.05rem;
