  border-radius: var(--radius-lg);
  padding: 28px 32px;
  margin-bottom: 32px;
}
.deal-banner h3 {
  font-family: 'Cormorant Garamond', Georgia, serif;
  font-size: 1.6rem;
  margin: 0 0 6px;
  font-weight: 500;
}
.deal-banner p { margin: 0; color: var(--text-muted); }
.countdown {
  display: flex;
  gap: 10px;
}
.countdown div {
  background: var(--bg);
  border: 1px solid var(--border);
  border-radius: 8px;
  padding: 10px 14px;
  min-width: 64px;
  text-align: center;
}
.countdown .num {
  font-size: 1.4rem;
  font-weight: 700;
  font-variant-numeric: tabular-nums;
  color: var(--accent);
