/* ==== Editorial ==== */
.editorial-grid {
  display: grid;
  grid-template-columns: 2fr 1fr 1fr;
  grid-template-rows: 1fr 1fr;
  gap: 20px;
  min-height: 560px;
}
.editorial-card {
  position: relative;
  border-radius: var(--radius-lg);
  overflow: hidden;
  background: var(--bg-elev);
  border: 1px solid var(--border);
  display: flex;
  flex-direction: column;
  justify-content: flex-end;
  min-height: 220px;
  isolation: isolate;
}
.editorial-card:nth-child(1) { grid-row: 1 / span 2; }
.editorial-bg {
  position: absolute;
  inset: 0;
  z-index: -1;
}
.editorial-bg svg { width: 100%; height: 100%; }
.editorial-card::after {
  content: "";
  position: absolute; inset: 0;
  background: linear-gradient(180deg, rgba(11,12,16,0) 30%, rgba(11,12,16,0.92) 100%);
