}
.editorial-card h3 {
  font-family: 'Cormorant Garamond', Georgia, serif;
  font-size: 1.4rem;
  margin: 0 0 6px;
  font-weight: 500;
  line-height: 1.2;
}
.editorial-card:nth-child(1) h3 { font-size: 2rem; }
.editorial-card p {
