      </div>
    </div>
  </section>
);

const Newsletter = ({ announce }) => {
  const id = useId();
  const [email, setEmail] = useState("");
  const [error, setError] = useState("");
  const [success, setSuccess] = useState("");
  const inputRef = useRef(null);

  const onSubmit = (e) => {
    e.preventDefault();
    const value = email.trim();
    if (!value) {
      setError("Please enter your email address.");
      setSuccess("");
      inputRef.current?.focus();
      return;
    }
    if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(value)) {
      setError("Please enter a valid email address (e.g. you@example.com).");
      setSuccess("");
      inputRef.current?.focus();
      return;
    }
    setError("");
    setSuccess("Thanks — you're on the list. Check your inbox to confirm.");
    setEmail("");
    announce("You have been subscribed to the Noctis newsletter.");
  };

  return (
    <section className="newsletter" aria-labelledby="nl-h">
      <div className="container newsletter-inner">
        <div>
          <h2 id="nl-h">Letters from Noctis</h2>
          <p>Monthly. New arrivals, the occasional essay, and members-only sales. Unsubscribe anytime.</p>
        </div>
        <form className="newsletter-form" onSubmit={onSubmit} noValidate>
          <div className="field">
            <label htmlFor={`${id}-email`}>Email address</label>
            <input
              ref={inputRef}
              id={`${id}-email`}
              type="email"
              autoComplete="email"
              required
              value={email}
              onChange={(e) => setEmail(e.target.value)}
              aria-invalid={error ? "true" : "false"}
              aria-describedby={
                [error && `${id}-err`, success && `${id}-ok`].filter(Boolean).join(" ") || undefined
              }
            />
            {error && <p id={`${id}-err`} className="field-error">{error}</p>}
          </div>
          <button type="submit" className="btn btn-primary">Subscribe</button>
          {success && (
            <p id={`${id}-ok`} className="field-success" role="status">{success}</p>
          )}
        </form>
      </div>
    </section>
  );
};

