/* ---------- App root ---------- */

const App = () => {
  const [wishlist, setWishlist] = useState(() => new Set());
  const [cartCount, setCartCount] = useState(2);

  const announce = (msg) => {
    const el = document.getElementById("status-region");
    if (!el) return;
    el.textContent = "";
    // ensure SR re-announces
    setTimeout(() => { el.textContent = msg; }, 50);
  };

  const onWishlistChange = (id) => {
    setWishlist(prev => {
      const next = new Set(prev);
      if (next.has(id)) {
        next.delete(id);
        announce("Removed from wishlist.");
      } else {
        next.add(id);
        announce("Added to wishlist.");
      }
      return next;
    });
  };

  const onAddToBag = () => setCartCount(c => c + 1);

