const ProductCard = ({ product, onWishlistChange, isWished, onAddToBag }) => {
  const { id, name, cat, price, was, rating, reviews, badge, hue } = product;
  const headingId = `p-${id}-name`;
  const save = was ? Math.round(((was - price) / was) * 100) : null;
  return (
    <article className="product-card" aria-labelledby={headingId}>
      <div className="product-media">
        <ArtTile hue={hue} name={id} />
        {badge === "sale" && <span className="product-badge sale">Sale</span>}
        {badge === "new"  && <span className="product-badge new">New</span>}
        <button
          type="button"
          className="wishlist-btn"
          aria-pressed={isWished}
          aria-label={`${isWished ? "Remove" : "Add"} ${name} ${isWished ? "from" : "to"} wishlist`}
