const Countdown = ({ targetMs }) => {
  const [now, setNow] = useState(Date.now());
  useEffect(() => {
    const t = setInterval(() => setNow(Date.now()), 1000);
    return () => clearInterval(t);
  }, []);
  const diff = Math.max(0, targetMs - now);
  const days = Math.floor(diff / 86400000);
  const hrs  = Math.floor((diff % 86400000) / 3600000);
  const mins = Math.floor((diff % 3600000) / 60000);
  const secs = Math.floor((diff % 60000) / 1000);
  const pad = (n) => String(n).padStart(2, "0");
  return (
    <div
      className="countdown"
      role="timer"
      aria-live="off"
      aria-label={`Sale ends in ${days} days, ${hrs} hours, ${mins} minutes`}
    >
      <div><span className="num">{pad(days)}</span><span className="lbl">Days</span></div>
      <div><span className="num">{pad(hrs)}</span><span className="lbl">Hrs</span></div>
      <div><span className="num">{pad(mins)}</span><span className="lbl">Min</span></div>
      <div><span className="num">{pad(secs)}</span><span className="lbl">Sec</span></div>
    </div>
  );
};

const DealsSection = ({ wishlist, onWishlistChange, onAddToBag }) => {
  // Target: 3 days from page load
