        </header>
        <div className="deal-banner">
          <div>
            <h3>The Winter Sale</h3>
            <p>Outerwear, accessories, and home pieces &mdash; while stocks last.</p>
          </div>
          <Countdown targetMs={target.current} />
        </div>
        <ProductGrid
          products={DEALS}
