const EditorialCard = ({ item }) => (
  <article className="editorial-card" aria-labelledby={`ed-${item.id}`}>
    <div className="editorial-bg" aria-hidden="true">
      <ArtTile hue={item.hue} sat={25} name={`ed-${item.id}`} />
    </div>
    <div className="editorial-body">
      <span className="editorial-tag">{item.tag}</span>
      <h3 id={`ed-${item.id}`}>{item.title}</h3>
      <p>{item.excerpt}</p>
      <a href={`#story-${item.id}`}>
        Read story <span className="visually-hidden">: {item.title}</span> →
      </a>
    </div>
  </article>
);

const EditorialSection = () => (
  <section id="editorial" aria-labelledby="ed-h">
    <div className="container">
      <header className="section-head">
        <div>
          <p className="kicker">The Journal</p>
          <h2 id="ed-h">Stories from after dark</h2>
          <p className="sub">Field notes, interviews, and quiet ideas from the Noctis editors.</p>
        </div>
        <a className="btn-link" href="#">All stories <Icon name="arrow" style={{ width: 14, height: 14 }} /></a>
      </header>
      <div className="editorial-grid">
        {EDITORIAL.map(item => <EditorialCard key={item.id} item={item} />)}
      </div>
    </div>
  </section>
);

const Newsletter = ({ announce }) => {
  const id = useId();
  const [email, setEmail] = useState("");
  const [error, setError] = useState("");
  const [success, setSuccess] = useState("");
  const inputRef = useRef(null);

  const onSubmit = (e) => {
    e.preventDefault();
    const value = email.trim();
    if (!value) {
      setError("Please enter your email address.");
      setSuccess("");
      inputRef.current?.focus();
      return;
    }
    if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(value)) {
      setError("Please enter a valid email address (e.g. you@example.com).");
      setSuccess("");
      inputRef.current?.focus();
      return;
    }
    setError("");
    setSuccess("Thanks — you're on the list. Check your inbox to confirm.");
    setEmail("");
    announce("You have been subscribed to the Noctis newsletter.");
  };

  return (
    <section className="newsletter" aria-labelledby="nl-h">
      <div className="container newsletter-inner">
        <div>
          <h2 id="nl-h">Letters from Noctis</h2>
