        <form className="newsletter-form" onSubmit={onSubmit} noValidate>
          <div className="field">
            <label htmlFor={`${id}-email`}>Email address</label>
            <input
              ref={inputRef}
              id={`${id}-email`}
              type="email"
              autoComplete="email"
              required
              value={email}
              onChange={(e) => setEmail(e.target.value)}
              aria-invalid={error ? "true" : "false"}
              aria-describedby={
                [error && `${id}-err`, success && `${id}-ok`].filter(Boolean).join(" ") || undefined
              }
